// Simulación de Gatling en Scala reutilizando el feature de Karate
val protocol = karateProtocol(
  "/api/v1/funds/{id}" -> Nil
)

val scn = scenario("Carga de Consulta de Fondos").exec(karateFeature("classpath:funds.feature"))

setUp(
  scn.inject(
    rampUsers(200).during(30.seconds)
  ).protocols(protocol)
).assertions(
  global.responseTime.percentile3.lt(250), // p95 menor a 250ms
  global.successfulRequests.percent.gt(99.9) // 99.9% de éxito
)
